import React, { useState } from 'react';

// Create the App component here
const App = () => {
  // Initialize state here
  const [isVisible, setIsVisible] = useState<boolean>(false);

  // Define the handler function here
  const handleToggle = () => {
    setIsVisible(prev => !prev);
  };

  return (
    <>
      <Header title="Component Composition Demo" />
      <Card title="First Card" content="This is the first card's content" />
      <Card title="Second Card" content="This is the second card's content" />
      {/* Add button and conditional paragraph here */}
    </>
  );
};

// Create the Card component below
interface CardProps {
  title: string;
  content: string;
}

const Card = ({ title, content }: CardProps) => {
  return (
    <div style={{ border: '1px solid #ccc', padding: '1rem', margin: '1rem' }}>
      <h3>{title}</h3>
      <p>{content}</p>
    </div>
  );
};

// Create the Header component here
const Header = ({ title }: { title: string }): JSX.Element => {
  return (
    <header style={{ backgroundColor: '#333', color: '#fff', padding: '1rem' }}>
      <h1>{title}</h1>
    </header>
  );
};

export default App;
